import { gql } from '@apollo/client'

export const EvidenceList  = gql`
  query demEvidenceList(
    $groupId: String!
  ) {
    demEvidenceList(
      where: { group: { id: $groupId } }
    ) {
      id
      fileUrl
      thumbnailUrl
      recordedAt
      duration
      officer {
        id
        name
      }
    }
  }
`

export interface EvidenceListArgs {
  groupId: string;
}

export interface EvidenceListRes {
  demEvidenceList: {
    id: string;
    fileUrl: string;
    thumbnailUrl: string;
    recordedAt: string;
    duration: number;
    officer: {
      id: string;
      name: string;
    }
  }[]
}