import React from "react";
import { Breadcrumb } from "antd";
import { useQuery } from '@apollo/client'
import { Link } from 'react-router-dom'
import moment from 'moment-timezone'
import styled from 'styled-components'
import { Table, Tag } from 'antd';

import { useStoreState } from 'state'
import {
  EvidenceList as query,
  EvidenceListArgs,
  EvidenceListRes
} from 'graphql-src/evidence/queries'
import PageHeader from "components/layout-components/PageHeader";

const Thumbnail = styled.img`
  width: 180px;
  min-height: 95px;
  background: #000;
`

const EvidenceList = (props: any) => {
  const groups = useStoreState(state => state.user.demGroups)

  console.log('groups', groups)

  const columns = [
    {
      title: '',
      dataIndex: 'thumbnail',
      key: 'thumbnail',
      render: ({ url, id }:{ url: string; id: string; }) => <Link to={`/app/evidence/view/${id}`} ><Thumbnail src={url} /></Link>,
    },
    {
      title: 'Officer',
      dataIndex: 'name',
      key: 'name',
    },
    {
      title: 'Duration',
      dataIndex: 'duration',
      key: 'duration',
    },
    {
      title: 'Recorded At',
      dataIndex: 'date',
      key: 'date',
    },
    {
      title: 'Tags',
      key: 'tags',
      dataIndex: 'tags',
      render: (tags: string[]) => (
        <>
          {tags.map(tag => {
            let color = tag.length > 5 ? 'geekblue' : 'green';
            if (tag === 'loser') {
              color = 'volcano';
            }
            return (
              <Tag color={color} key={tag}>
                {tag.toUpperCase()}
              </Tag>
            );
          })}
        </>
      ),
    }
  ];

  const { data } = useQuery<EvidenceListRes, EvidenceListArgs>(query, {
    variables: { groupId: groups.length > 0 ? groups[0].groupId : '' },
    fetchPolicy: 'cache-and-network'
  })

  return (
    <div>
      <PageHeader
        title="Evidence List"
        display={true}
        breadcrumbs={
          <Breadcrumb>
            <Breadcrumb.Item>Home</Breadcrumb.Item>
            <Breadcrumb.Item>
              <Link to="/app/evidence/list">Evidence List</Link>
            </Breadcrumb.Item>
          </Breadcrumb>
        }
      />
      <Table 
        columns={columns}
        dataSource={data?.demEvidenceList.map(({
          id,
          officer,
          thumbnailUrl,
          recordedAt,
          duration
        }) => ({
          key: id,
          thumbnail: { id, url: thumbnailUrl },
          name: officer.name,
          date: moment(recordedAt).tz('America/New_York').format('HH:mm - DD/MM/YY'),
          duration: moment.utc(duration*1000).format('HH:mm:ss'),
          tags: [],
        }))}
        loading={data ? false : true || groups.length === 0}
        onRow={(record) => {
          return {
            onClick: () => props.history.push(`/app/evidence/view/${record.key}`), // click row
          };
        }}
        rowClassName="clickable-row"
      />
    </div>
  );
};

export default EvidenceList;
